    explanation: "本题考查作家作品。《四世同堂》是作家老舍所创作的长篇小说，该小说是一部表现抗战时期北平沦陷区普通民众生活与抗战的长篇小说，全书共三部，《惶惑》《偷生》《饥荒》，这部小说以祁家四世同堂的生活为主线，讲述了以小羊圈胡同住户为代表的各个阶层、各色人等的荣辱浮沉、生死存亡的故事。故选A。"
